CREATE TABLE IF NOT EXISTS cases ( id TEXT PRIMARY KEY, client_uuid TEXT UNIQUE, person_id TEXT NOT NULL, worker_id TEXT NOT NULL, visit_type TEXT NOT NULL DEFAULT 'baseline' CHECK (visit_type IN ('baseline','followup','problem')), status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted','info_requested','opinion','closed','withdrawn')), urgency TEXT NOT NULL DEFAULT 'routine' CHECK (urgency IN ('routine','urgent')), red_flags TEXT NOT NULL DEFAULT '[]', age_band TEXT, sex TEXT, district TEXT, lsgd_type TEXT, bedbound INTEGER, claimed_by TEXT, claim_expires TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), submitted_at TEXT NOT NULL DEFAULT (datetime('now')), opinion_at TEXT, escalated_at TEXT, sampled_for_audit INTEGER NOT NULL DEFAULT 0 );
CREATE INDEX IF NOT EXISTS idx_cases_status ON cases(status, urgency, submitted_at);
CREATE INDEX IF NOT EXISTS idx_cases_person ON cases(person_id);
CREATE INDEX IF NOT EXISTS idx_cases_worker ON cases(worker_id);
CREATE TABLE IF NOT EXISTS screenings ( case_id TEXT PRIMARY KEY REFERENCES cases(id), ohat TEXT NOT NULL, ohat_total INTEGER, gohai TEXT, gohai_total INTEGER, natural_teeth INTEGER, functional_dentition INTEGER, denture_upper TEXT, denture_lower TEXT, denture_fit TEXT, complaints TEXT NOT NULL DEFAULT '[]', complaint_text TEXT, complaint_lang TEXT, risks TEXT NOT NULL DEFAULT '{}', context TEXT NOT NULL DEFAULT '{}', medicines TEXT NOT NULL DEFAULT '[]', medicine_flags TEXT NOT NULL DEFAULT '[]', worker_notes TEXT, worker_notes_lang TEXT );
CREATE TABLE IF NOT EXISTS images ( id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), view TEXT NOT NULL, media_key TEXT NOT NULL, mime TEXT NOT NULL DEFAULT 'image/jpeg', width INTEGER, height INTEGER, bytes INTEGER, quality REAL, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_images_case ON images(case_id);
CREATE TABLE IF NOT EXISTS opinions ( id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), version INTEGER NOT NULL DEFAULT 1, dentist_id TEXT NOT NULL, findings TEXT, impression TEXT, impression_codes TEXT NOT NULL DEFAULT '[]', advice TEXT, care_plan TEXT, note TEXT, text_lang TEXT NOT NULL DEFAULT 'en', followup_months INTEGER, referral_needed INTEGER NOT NULL DEFAULT 0, referral_type TEXT, referral_urgency TEXT, referral_message TEXT, cannot_assess INTEGER NOT NULL DEFAULT 0, kb_items TEXT NOT NULL DEFAULT '[]', verify_code TEXT NOT NULL UNIQUE, signed_at TEXT NOT NULL DEFAULT (datetime('now')), superseded_by TEXT, correction_reason TEXT );
CREATE INDEX IF NOT EXISTS idx_opinions_case ON opinions(case_id);
CREATE TABLE IF NOT EXISTS info_requests ( id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), dentist_id TEXT NOT NULL, message TEXT NOT NULL, message_lang TEXT, response TEXT, response_lang TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), resolved_at TEXT );
CREATE TABLE IF NOT EXISTS referral_centres ( id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT, services TEXT, address TEXT, district TEXT, timings TEXT, phone TEXT, cost_category TEXT, accessibility TEXT, active INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS referrals ( id TEXT PRIMARY KEY, case_id TEXT NOT NULL UNIQUE REFERENCES cases(id), centre_id TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','reached','not_reached')), reached_date TEXT, treatment TEXT, barrier TEXT, recorded_by TEXT, recorded_at TEXT );
CREATE TABLE IF NOT EXISTS kb_items ( id TEXT PRIMARY KEY, title TEXT NOT NULL, title_ml TEXT, kind TEXT NOT NULL CHECK (kind IN ('video','leaflet','pictogram','training')), url TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'ml', audience TEXT NOT NULL DEFAULT 'patient' CHECK (audience IN ('patient','caregiver','worker','dentist')), tags TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, approved_by TEXT, approved_at TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS audits ( id TEXT PRIMARY KEY, opinion_id TEXT NOT NULL UNIQUE REFERENCES opinions(id), auditor_id TEXT NOT NULL, rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5), safe INTEGER NOT NULL, notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS followups ( id TEXT PRIMARY KEY, person_id TEXT NOT NULL, worker_id TEXT NOT NULL, due_date TEXT NOT NULL, reason TEXT NOT NULL DEFAULT 'rescreen', source_case_id TEXT, status TEXT NOT NULL DEFAULT 'due' CHECK (status IN ('due','done','cancelled')), done_case_id TEXT );
CREATE INDEX IF NOT EXISTS idx_followups_worker ON followups(worker_id, status, due_date);
CREATE TABLE IF NOT EXISTS translations ( hash TEXT PRIMARY KEY, src_lang TEXT NOT NULL, tgt_lang TEXT NOT NULL, out_text TEXT NOT NULL, engine TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS glossary ( id TEXT PRIMARY KEY, en TEXT NOT NULL UNIQUE, ml TEXT NOT NULL, notes TEXT );
CREATE TABLE IF NOT EXISTS lsgds ( id TEXT PRIMARY KEY, state TEXT NOT NULL, district TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, name_ml TEXT, lgd_code TEXT );
CREATE INDEX IF NOT EXISTS idx_lsgds_district ON lsgds(state, district);
CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS audit_log ( id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL DEFAULT (datetime('now')), user_id TEXT, role TEXT, action TEXT NOT NULL, object_type TEXT, object_id TEXT, detail TEXT );
CREATE INDEX IF NOT EXISTS idx_audit_at ON audit_log(at);
INSERT OR IGNORE INTO settings(key, value) VALUES ('claim_minutes','30'), ('sla_urgent_hours','24'), ('sla_routine_hours','72'), ('audit_sample_percent','10'), ('consent_notice_version','2026-10-draft'), ('small_cell_threshold','10');
INSERT OR IGNORE INTO settings (key, value) VALUES ('org_legal_name', 'Community Innovation Foundation'), ('org_address', ''), ('grievance_name', ''), ('grievance_phone', ''), ('grievance_email', ''), ('retention_years', '5'), ('grievance_days', '30');
DELETE FROM settings WHERE key = 'consent_notice_version';
CREATE TABLE IF NOT EXISTS questionnaires ( version INTEGER PRIMARY KEY, content TEXT NOT NULL, note TEXT NOT NULL, restored_from INTEGER, created_by TEXT NOT NULL, created_by_name TEXT, created_by_role TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
ALTER TABLE screenings ADD COLUMN questionnaire_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE screenings ADD COLUMN extra TEXT NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS institutions ( id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'dental_college', state TEXT, district TEXT, address TEXT, phone TEXT, email TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
ALTER TABLE cases ADD COLUMN state TEXT;
ALTER TABLE cases ADD COLUMN institution_id TEXT;
ALTER TABLE cases ADD COLUMN assigned_to TEXT;
ALTER TABLE cases ADD COLUMN assigned_by TEXT;
ALTER TABLE cases ADD COLUMN assigned_at TEXT;
ALTER TABLE cases ADD COLUMN worker_lang TEXT;
CREATE INDEX IF NOT EXISTS idx_cases_state ON cases(state, district);
CREATE INDEX IF NOT EXISTS idx_cases_institution ON cases(institution_id);
ALTER TABLE opinions ADD COLUMN institution_id TEXT;
ALTER TABLE opinions ADD COLUMN institution_name TEXT;
CREATE INDEX IF NOT EXISTS idx_opinions_institution ON opinions(institution_id);
UPDATE cases SET state = CASE WHEN district IN ('Thiruvananthapuram','Kollam','Pathanamthitta','Alappuzha','Kottayam','Idukki','Ernakulam','Thrissur','Palakkad','Malappuram','Kozhikode','Wayanad','Kannur','Kasaragod') THEN 'Kerala' WHEN district IN ('Ariyalur','Chengalpattu','Chennai','Coimbatore','Cuddalore','Dharmapuri','Dindigul','Erode','Kallakurichi','Kancheepuram','Kanniyakumari','Karur','Krishnagiri','Madurai','Mayiladuthurai','Nagapattinam','Namakkal','Nilgiris','Perambalur','Pudukkottai','Ramanathapuram','Ranipet','Salem','Sivaganga','Tenkasi','Thanjavur','Theni','Thoothukudi','Tiruchirappalli','Tirunelveli','Tirupathur','Tiruppur','Tiruvallur','Tiruvannamalai','Tiruvarur','Vellore','Viluppuram','Virudhunagar') THEN 'Tamil Nadu' WHEN district IN ('Bagalkote','Ballari','Belagavi','Bengaluru Rural','Bengaluru Urban','Bengaluru South (Ramanagara)','Bidar','Chamarajanagar','Chikkaballapura','Chikkamagaluru','Chitradurga','Dakshina Kannada','Davanagere','Dharwad','Gadag','Hassan','Haveri','Kalaburagi','Kodagu','Kolar','Koppal','Mandya','Mysuru','Raichur','Shivamogga','Tumakuru','Udupi','Uttara Kannada','Vijayanagara','Vijayapura','Yadgir') THEN 'Karnataka' WHEN district IN ('Alluri Sitharama Raju','Anakapalli','Anantapur','Annamayya','Bapatla','Chittoor','Dr. B.R. Ambedkar Konaseema','East Godavari','Eluru','Guntur','Kakinada','Krishna','Kurnool','Nandyal','NTR','Palnadu','Parvathipuram Manyam','Prakasam','Sri Potti Sriramulu Nellore','Sri Sathya Sai','Srikakulam','Tirupati','Visakhapatnam','Vizianagaram','West Godavari','YSR Kadapa') THEN 'Andhra Pradesh' WHEN district IN ('Adilabad','Bhadradri Kothagudem','Hanumakonda','Hyderabad','Jagtial','Jangaon','Jayashankar Bhupalpally','Jogulamba Gadwal','Kamareddy','Karimnagar','Khammam','Kumuram Bheem Asifabad','Mahabubabad','Mahabubnagar','Mancherial','Medak','Medchal-Malkajgiri','Mulugu','Nagarkurnool','Nalgonda','Narayanpet','Nirmal','Nizamabad','Peddapalli','Rajanna Sircilla','Rangareddy','Sangareddy','Siddipet','Suryapet','Vikarabad','Wanaparthy','Warangal','Yadadri Bhuvanagiri') THEN 'Telangana' WHEN district IN ('Ahilyanagar (Ahmednagar)','Akola','Amravati','Beed','Bhandara','Buldhana','Chandrapur','Chhatrapati Sambhajinagar (Aurangabad)','Dharashiv (Osmanabad)','Dhule','Gadchiroli','Gondia','Hingoli','Jalgaon','Jalna','Kolhapur','Latur','Mumbai City','Mumbai Suburban','Nagpur','Nanded','Nandurbar','Nashik','Palghar','Parbhani','Pune','Raigad','Ratnagiri','Sangli','Satara','Sindhudurg','Solapur','Thane','Wardha','Washim','Yavatmal') THEN 'Maharashtra' ELSE NULL END WHERE state IS NULL;
UPDATE cases SET worker_lang = CASE state WHEN 'Kerala' THEN 'ml' WHEN 'Tamil Nadu' THEN 'ta' WHEN 'Karnataka' THEN 'kn' WHEN 'Andhra Pradesh' THEN 'te' WHEN 'Telangana' THEN 'te' WHEN 'Maharashtra' THEN 'mr' ELSE 'en' END WHERE worker_lang IS NULL;
INSERT OR IGNORE INTO settings (key, value) VALUES ('assign_hours', '48');
